// Independent user-intent and mechanical acceptance; all forces remain in the real Vehicle core.
#define main driveability_diagnostic_main
#include "DriveabilityStudy.cpp"
#undef main
#include <limits>
static int Checks=0,Failures=0;
static void Check(const char* name,bool pass,double value=0){++Checks;if(!pass)++Failures;std::printf("%s | %s | %.15g\n",pass?"PASS":"FAIL",name,value);}
static bool Near(double a,double b,double tol=1e-8){return std::isfinite(a)&&std::isfinite(b)&&std::fabs(a-b)<tol;}
int main(){
Vehicle defaultCar=Car();Check("assisted steering has an explicit default and .85 headroom",defaultCar.Set.bAssistedSteering&&Near(defaultCar.Set.SteeringGripHeadroom,.85));Check("stock peak friction coefficient is unchanged",Near(defaultCar.S.PeakMu,1.45),defaultCar.S.PeakMu);
Inputs right;right.Steer=1;
Vehicle parking=Car(),parkingRaw=parking;parkingRaw.Set.bAssistedSteering=false;parking.Step(.001,right,Ground);parkingRaw.Step(.001,right,Ground);Check("parking retains full physical rack request",Near(parking.T.SteeringAppliedRad,32*kPi/180)&&Near(parking.T.SteeringAppliedRad,parkingRaw.T.SteeringAppliedRad),parking.T.SteeringAppliedRad*180/kPi);Check("right turn Ackermann gives inside right wheel the larger positive angle",parking.Wheels[1].Steer>parking.Wheels[0].Steer&&parking.Wheels[0].Steer>0,parking.Wheels[1].Steer*180/kPi);
Vehicle state=Car(35),assisted=state,raw=state;raw.Set.bAssistedSteering=false;double front=0,rear=0;for(const auto&w:state.Wheels)(w.bFront?front:rear)+=state.S.PeakMu*w.GripFactor*w.Load;const double share=.5+state.S.CGForward/state.S.Wheelbase;const double independentAy=.85*std::min(front/(state.TotalMass()*share),rear/(state.TotalMass()*(1-share)));assisted.Step(.001,right,Ground);raw.Step(.001,right,Ground);const double demand=35*35*std::tan(std::fabs(assisted.T.SteeringAppliedRad))/assisted.S.Wheelbase;
Check("high speed full request is limited before tire saturation",assisted.T.bSteeringLimited&&std::fabs(assisted.T.SteeringAppliedRad)<.5*std::fabs(raw.T.SteeringAppliedRad),assisted.T.SteeringAppliedRad*180/kPi);Check("unperturbed rack curvature obeys independent axle grip budget",demand<=independentAy*(1+1e-7),demand/independentAy);Check("Raw preserves the unrestricted speed-sensitive rack request",Near(raw.T.SteeringAppliedRad,raw.T.SteeringRequestRad)&&!raw.T.bSteeringLimited,raw.T.SteeringAppliedRad*180/kPi);
Vehicle noESC=state;noESC.Set.bESC=false;noESC.Set.bTCS=false;noESC.Step(.001,right,Ground);Check("steering guard remains independent of ESC and TCS",Near(noESC.T.SteeringAppliedRad,assisted.T.SteeringAppliedRad)&&noESC.T.bSteeringLimited,noESC.T.SteeringAppliedRad*180/kPi);
Vehicle low=state,high=state;low.Set.SteeringGripHeadroom=.5;high.Set.SteeringGripHeadroom=1;low.Step(.001,right,Ground);high.Step(.001,right,Ground);Check("user headroom changes permitted request monotonically",low.T.SteeringGripLimitRad<high.T.SteeringGripLimitRad,high.T.SteeringGripLimitRad/low.T.SteeringGripLimitRad);
for(double invalid:{std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity()}){Vehicle bad=state;bad.Set.SteeringGripHeadroom=invalid;bad.Step(.001,right,Ground);Check("nonfinite headroom falls back to finite default steering",Near(bad.T.SteeringAppliedRad,assisted.T.SteeringAppliedRad),bad.T.SteeringAppliedRad);}
for(double side:{-4.,4.}){Vehicle catchCar=state;catchCar.V.y=side;Inputs catchInput;catchInput.Steer=Sign(side);catchCar.Step(.001,catchInput,Ground);Check("driver countersteer retains requested direction and extra catch authority",Sign(catchCar.T.SteeringAppliedRad)==Sign(side)&&std::fabs(catchCar.T.SteeringAppliedRad)>std::fabs(assisted.T.SteeringAppliedRad)+.02,catchCar.T.SteeringAppliedRad*180/kPi);}
for(bool reverse:{false,true})for(double sign:{-1.,1.}){Vehicle turn=Car(reverse?-8:15,reverse);Inputs in;in.Steer=sign*.2;in.bWantReverse=reverse;in.Throttle=reverse?0:.2;for(int k=0;k<500;++k)turn.Step(.001,in,Ground);const double yaw=turn.Q.Unrotate(turn.W).z;Check("forward and reverse steering produce correct mirrored yaw",yaw*sign*(reverse?-1:1)>.01,yaw);}
for(Trim tr:{Trim::Performance,Trim::Thrust,Trim::Rocket}){Vehicle v;v.Init(tr);v.Set.Aero=AeroPreset::Custom;v.Set.Fan=FanMode::Off;v.Place({0,0,0},Quat());Inputs in;for(int k=0;k<4000;++k)v.Step(.001,in,Ground);double total=0,frontLoad=0;for(const auto&w:v.Wheels){total+=w.Load;if(w.bFront)frontLoad+=w.Load;}const double expected=.5+v.S.CGForward/v.S.Wheelbase;std::printf("STATIC %s frontFraction=%.9f expected=%.9f pitch=%.9fdeg bodyZ=%.9f\n",TrimName(tr),frontLoad/total,expected,std::asin(v.Q.Fwd().z)*180/kPi,v.BodyOriginWorld().z);Check("settled wheel loads follow rearward-CG static moment balance",std::fabs(frontLoad/total-expected)<.01,frontLoad/total);Check("correct preload keeps settled body nearly level",std::fabs(v.Q.Fwd().z)<.01,v.Q.Fwd().z);}
Vehicle warm=state,cold=state,worn=state;for(auto&w:warm.Wheels)w.SurfaceTempC=85;for(auto&w:worn.Wheels)w.Wear=1;for(int k=0;k<4;++k){warm.Step(.001,right,Ground);cold.Step(.001,right,Ground);worn.Step(.001,right,Ground);}Check("grip guard follows existing tire temperature and wear factors",warm.T.SteeringGripLimitRad>=cold.T.SteeringGripLimitRad&&worn.T.SteeringGripLimitRad<cold.T.SteeringGripLimitRad,worn.T.SteeringGripLimitRad/cold.T.SteeringGripLimitRad);
std::printf("RESULT %d/%d passed\n",Checks-Failures,Checks);return Failures?1:0;}
